<?php declare(strict_types=1); namespace App\Domains\Appointment\Policies; use App\Domains\User\Models\User; use App\Domains\Appointment\Models\Appointment;
final class AppointmentPolicy { public function viewAny(User $u): bool { return true; } public function view(User $u, Appointment $a): bool { return $u->organization_id === $a->organization_id; } public function create(User $u): bool { return true; } public function update(User $u, Appointment $a): bool { return $u->hasRole(['Super Admin','Owner','Dentist']) && $u->organization_id === $a->organization_id; } public function delete(User $u, Appointment $a): bool { return $u->hasRole(['Super Admin','Owner']) && $u->organization_id === $a->organization_id; } }
